def verify_isbn(isbn: str) -> str:
    def calculate_checksum(parts):
        # Unpack parts
        part1, part2, part3, checksum = parts

        # Calculate the checksum
        total = sum((int(part1[i]) * (i + 1) for i in range(3)))
        total += sum((int(part2[i]) * (i + 4) for i in range(3)))
        total += sum((int(part3[i]) * (i + 7) for i in range(5)))

        # Calculate the checksum digit
        checksum_digit = total % 11
        if checksum_digit == 10:
            return 'X'
        else:
            return str(checksum_digit)

    # Split the ISBN into parts
    parts = isbn.split('-')
    if len(parts) != 4:
        return "Invalid Format"

    # Extract and prepare parts
    part1, part2, part3, checksum = parts
    if len(part1) != 1 or len(part2) != 3 or len(part3) != 5:
        return "Invalid Format"

    # Calculate the correct checksum
    correct_checksum = calculate_checksum(parts[:-1])

    # Verify the ISBN
    if checksum.upper() == correct_checksum:
        return "Right"
    else:
        return f"{part1}-{part2}-{part3}-{correct_checksum}"

