def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = '-' if coeff < 0 else '+'
        if abs(coeff) == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs(coeff))
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''
        if not terms:
            if sign == '+':
                terms.append(f'{coeff_str}{var_str}')
            else:
                terms.append(f'-{coeff_str}{var_str}')
        else:
            terms.append(f'{sign}{coeff_str}{var_str}')
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) != 26:
        return "Failed"

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

