def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or k == 0:
        return 0
    if k == 1:
        return 1 if n >= x else 0

    # Initialize a table to store results of subproblems
    dp = [[0 for _ in range(n + 1)] for _ in range(k + 1)]

    # Base case: If n = 0 and k = 0, then 1 way to partition
    dp[0][0] = 1

    # Base case: If n > 0 and k = 0, then no way to partition
    for i in range(1, n + 1):
        dp[0][i] = 0

    # Fill the partition table in bottom up manner
    for i in range(1, k + 1):
        for j in range(1, n + 1):
            if j < i * x:
                dp[i][j] = 0
            else:
                dp[i][j] = dp[i - 1][j] + dp[i][j - i * x]

    return dp[k][n]

