    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    from math import gcd
    if y0 % x0 != 0:
        return 0
    quotient = y0 // x0
    count = 0
    for a in range(1, int(quotient**0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

