    queue = deque([(A, 0)])  # (current_string, current_step)
    visited = set([A])

    while queue:
        current_string, current_step = queue.popleft()

        if current_step > 10:
            continue

        if current_string == B:
            return current_step

        for src, target in rules:
            start = 0
            while start <= len(current_string) - len(src):
                pos = current_string.find(src, start)
                if pos != -1:
                    new_string = current_string[:pos] + target + current_string[pos + len(src):]
                    if new_string not in visited:
                        visited.add(new_string)
                        queue.append((new_string, current_step + 1))
                else:
                    break
                start = pos + 1

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    """Determine whether a given integer is a prime number."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Convert the number to a string for easy digit access
    original_str = str(n)
    # Create a dictionary for quick lookup of transformation rules
    transform_dict = defaultdict(set)
    for x, y in rules:
        transform_dict[str(x)].add(str(y))

    # Use a queue for BFS
    queue = deque([original_str])
    # Use a set to track unique numbers
    unique_numbers = set([original_str])

    while queue:
        current_str = queue.popleft()
        for i in range(len(current_str)):
            current_digit = current_str[i]
            if current_digit in transform_dict:
                for new_digit in transform_dict[current_digit]:
                    new_str = current_str[:i] + new_digit + current_str[i+1:]
                    if new_str not in unique_numbers:
                        unique_numbers.add(new_str)
                        queue.append(new_str)

    # Convert the unique strings back to integers and return the count
    return len(unique_numbers)

