def jinjin_savings_plan(budgets: List[int]) -> int:
    pocket_money = 300
    savings_rate = 0.2
    total_savings = 0

    for month, budget in enumerate(budgets, start=1):
        remaining_money = pocket_money - budget
        if remaining_money < 100:
            return -month
        savings = (remaining_money // 100) * 100
        total_savings += savings

    total_savings_with_interest = total_savings * (1 + savings_rate)
    return int(total_savings_with_interest)

def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 2:
        return 0  # With 2 or fewer students, they can always form a choir

    left_increasing = [1] * n
    right_increasing = [1] * n

    # Calculate the longest increasing subsequence from the left
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            left_increasing[i] = left_increasing[i - 1] + 1

    # Calculate the longest increasing subsequence from the right
    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            right_increasing[i] = right_increasing[i + 1] + 1

    # Find the minimum number of students to remove
    min_students_to_leave = n
    for i in range(n):
        # The total length if we consider heights[i] as the peak
        total_length = left_increasing[i] + right_increasing[i] - 1
        min_students_to_leave = min(min_students_to_leave, n - total_length)

    return min_students_to_leave

def min_groups(w, n, prices):
    prices.sort()
    i, j = 0, n - 1
    groups = 0
    while i <= j:
        if prices[i] + prices[j] <= w:
            i += 1
        j -= 1
        groups += 1
    return groups

